function rows(count) {
  const out = [];
  for (let n = 0; n < count; n++) {
    const prev = out[n - 1] || [];
    const row = [];
    for (let k = 0; k <= n; k++) row.push(k === 0 || k === n ? 1 : prev[k - 1] + prev[k]);
    out.push(row);
  }
  return out;
}

function estimatedProbabilityOfSharedBirthday(groupSize) {
  const trials = 20000;
  let shared = 0;
  for (let t = 0; t < trials; t++) {
    const seen = new Set();
    for (let p = 0; p < groupSize; p++) {
      const day = Math.floor(Math.random() * 365);
      if (seen.has(day)) { shared++; break; }
      seen.add(day);
    }
  }
  return (100 * shared) / trials;
}
